{
    "name": "Full Pipeline",
    "version": 1,
    "status": "draft",
    "stages": [
        { "name": "Application", "stage_type": "application", "position": 1, "is_initial": true, "is_terminal": false },
        { "name": "Screening", "stage_type": "screening", "position": 2, "is_initial": false, "is_terminal": false },
        { "name": "Interview", "stage_type": "interview", "position": 3, "is_initial": false, "is_terminal": false },
        { "name": "Hired", "stage_type": "hired", "position": 4, "is_initial": false, "is_terminal": true },
        { "name": "Rejected", "stage_type": "rejected", "position": 5, "is_initial": false, "is_terminal": true }
    ]
}

{
    "name": "Full Screening Survey",
    "version": 1,
    "status": "active",
    "questions": [
        { "question_key": "experience", "label": "Do you have barista experience?", "type": "boolean", "is_required": true, "position": 1 },
        { "question_key": "availability", "label": "Are you available on weekends?", "type": "boolean", "is_required": true, "position": 2 },
        { "question_key": "years_exp", "label": "How many years of coffee experience?", "type": "number", "is_required": false, "position": 3 }
    ]
}

{
    "label": "Can you create advanced latte art?",
    "is_required": false
}

{
    "name": "Non-Disclosure Agreement",
    "document_type": "contract",
    "requires_signature": true,
    "description": "Standard NDA for all new employees.",
    "requirements": [
        { "workflow_stage_id": {{stage_id}}, "is_required": true, "due_days_after_stage_entry": 5 }
    ]
}
